    "translation": [
      "Bisakah Anda menjelaskan sekali lagi? Bisakah Anda menunggu sebentar? Besok ada ujian, soalnya. Saya sedang belajar bahasa Jepang, soalnya.",
      "Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang.",
      "Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Pada pagi hari waktu pelajaran diperiksa. Di kelas, siswa membaca bahasa Jepang dan mendengarkan penjelasan guru.",
      "Kosakata yang belum dipahami ditulis di buku catatan. Saat istirahat, siswa membicarakan isi pelajaran bersama teman. Setelah pulang, isi pelajaran hari itu diperiksa sekali lagi. Ada rencana belajar berikutnya yang akan dilakukan. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya."
    ],
