    "translation": [
      "Hari ini saya hanya belajar satu jam. Saya libur hanya hari Minggu. Hari ini saya hanya bisa belajar satu jam.",
      "Saya hanya bisa berbicara bahasa Jepang. Saya bisa berbicara bahasa Jepang. Besok saya bisa datang lebih awal.",
      "Ada rencana untuk hari berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya.",
      "Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Beberapa informasi diperiksa dari pagi hingga siang.",
      "Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali."
    ],
