    "translation": [
      "Saya bisa melakukannya sendiri. Dari sini Gunung Fuji bisa dilihat. Hari ini saya hanya bisa belajar satu jam. Libur saya hanya hari Minggu.",
      "Saya bisa berbicara bahasa Jepang. Ikan ini bisa dimakan mentah. Besok saya bisa datang lebih awal.",
      "Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu.",
      "Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan.",
      "Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Pada pagi hari, jadwal hari itu diperiksa terlebih dahulu. Kegiatan pagi dan sore sedikit berbeda. Waktu penting ditulis dalam catatan. Pada hari dengan banyak rencana, urutannya ditentukan."
    ],
