    "translation": [
      "Saya belajar bahasa Jepang untuk bekerja di Jepang. Saya belajar setiap hari untuk lulus ujian. Saya belajar bahasa Jepang sambil bekerja.",
      "Saya berbicara dengan teman sambil minum kopi. Saya bekerja keras demi keluarga. Tanaka baik hati dan juga pandai bahasa Jepang.",
      "Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik. Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Pada pagi hari waktu pelajaran diperiksa. Di kelas, siswa membaca bahasa Jepang dan mendengarkan penjelasan guru.",
      "Kosakata yang belum dipahami ditulis di buku catatan. Saat istirahat, siswa membicarakan isi pelajaran bersama teman. Setelah pulang, isi pelajaran hari itu diperiksa sekali lagi. Ada rencana belajar berikutnya yang akan dilakukan. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya.",
      "Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut."
    ],
