    "translation": [
      "Saya belajar bahasa Jepang sambil bekerja. Saya berbicara dengan teman sambil minum kopi. Hari ini hujan dan dingin, jadi saya di rumah. Tanaka baik hati dan juga pandai bahasa Jepang.",
      "Karena besok ujian, malam ini saya belajar. Saya belajar bahasa Jepang untuk bekerja di Jepang. Saya belajar setiap hari untuk lulus ujian.",
      "Di kelas, siswa membaca bahasa Jepang dan mendengarkan penjelasan guru. Kosakata yang belum dipahami ditulis di buku catatan. Saat istirahat, siswa membicarakan isi pelajaran bersama teman. Setelah pulang, isi pelajaran hari itu diperiksa sekali lagi. Ada rencana belajar berikutnya yang akan dilakukan. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya.",
      "Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat.",
      "Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Penulis menjelaskan alasan dan tindakan dengan hubungan sebab-akibat. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan."
    ],
