    "translation": [
      "Tolong biarkan jendelanya tetap terbuka. Saya akan memasukkan minuman ke kulkas sebagai persiapan. Jendelanya dalam keadaan terbuka.",
      "Lampunya menyala. Pintunya tertutup. Mobilnya sedang dalam keadaan berhenti/terparkir.",
      "Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Di rumah, jadwal keluarga diperiksa. Kamar dirapikan sedikit demi sedikit setiap hari. Pada sore hari, keluarga makan bersama. Pada akhir pekan, keluarga juga membersihkan rumah dan berbelanja. Karena waktu setiap orang berbeda, jadwal dibicarakan lebih dulu.",
      "Ada rencana keluarga berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya.",
      "Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Penulis menjelaskan alasan dan tindakan dengan hubungan sebab-akibat. Beberapa informasi diperiksa dari pagi hingga siang."
    ],
