      "Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik. Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami."
