    "translation": [
      "Setelah lulus, saya berniat bekerja. Minggu ini saya berniat tidak memakai mobil. Hari Minggu ada rencana perjalanan keluarga.",
      "Pesawat dijadwalkan tiba pukul enam sore. Bulan depan saya dijadwalkan dinas ke Osaka.",
      "Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik.",
      "Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Pada pagi hari, jadwal hari itu diperiksa terlebih dahulu. Kegiatan pagi dan sore sedikit berbeda. Waktu penting ditulis dalam catatan. Pada hari dengan banyak rencana, urutannya ditentukan. Pada akhirnya, jadwal hari berikutnya juga diperiksa."
    ],
