    "translation": [
      "Hari Minggu ada rencana perjalanan keluarga. Pesawat dijadwalkan tiba pukul enam sore. Saat libur musim panas saya berniat pulang ke negara asal.",
      "Setelah lulus, saya berniat bekerja. Bulan depan saya dijadwalkan dinas ke Osaka. Rapat dijadwalkan mulai pukul tiga.",
      "Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik. Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Pada pagi hari, jadwal hari itu diperiksa terlebih dahulu. Kegiatan pagi dan sore sedikit berbeda. Waktu penting ditulis dalam catatan. Pada hari dengan banyak rencana, urutannya ditentukan.",
      "Pada akhirnya, jadwal hari berikutnya juga diperiksa. Ada rencana untuk hari berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan.",
      "Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal."
    ],
